#!/usr/bin/env python3
"""answers_oct28.py | freepracticesat.com | Oct 28, 2026
Adds two answer posts (how long to raise your SAT math score, 550 to 700),
their cards at the top of the blog page, and four sitemap entries.
Changes nothing unless blog/index.html and sitemap.xml look as expected.
Undo: python3 answers_oct28.py --undo"""
import sys,os,json,base64,zlib,hashlib,shutil
C=json.loads('{"files": {"blog/how-long-to-raise-sat-math-score.html": {"d": "", "h": "ef2cd5646e68a257af546c4ab8acf54f0ef77988ec93e2ddadca5cb93c04fe33"}, "blog/sat-math-550-to-700.html": {"d": "", "h": "6e0a9fcfd1176fc9739623da4c684a1a96e10216ec1397e27911bd6e641a6b89"}}, "hr": "<hr class=\\"gold-rule\\">\\n", "cards": "<a class=\\"post-card\\" href=\\"/blog/how-long-to-raise-sat-math-score.html\\">\\n<p class=\\"meta\\">For Students &amp; Parents &middot; October 28, 2026</p>\\n<h2>How Long Does It Take to Raise Your SAT Math Score?</h2>\\n<p>What my students\' practice scores show, what College Board found, and how long different kinds of math gaps usually take to close.</p>\\n</a>\\n<a class=\\"post-card\\" href=\\"/blog/sat-math-550-to-700.html\\">\\n<p class=\\"meta\\">For Students &middot; October 28, 2026</p>\\n<h2>How Do I Go From 550 to 700 in SAT Math?</h2>\\n<p>One student on my site went from 570 to a best of 780 in six weeks. What changed along the way, and the order I would follow.</p>\\n</a>\\n", "smap": "  <url>\\n    <loc>https://freepracticesat.com/blog/how-long-to-raise-sat-math-score.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n  <url>\\n    <loc>https://freepracticesat.com/blog/sat-math-550-to-700.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n"}')
BK='.answers_backup_20261028'
EDIT=['blog/index.html','sitemap.xml']
sha=lambda b: hashlib.sha256(b).hexdigest()
rd=lambda p: open(p,'rb').read()
if '--undo' in sys.argv:
    if not os.path.isdir(BK): sys.exit('No backup found. Nothing undone.')
    for f in EDIT: shutil.copyfile(os.path.join(BK,f.replace('/','_')),f)
    for f in C['files']:
        if os.path.exists(f): os.rename(f,os.path.join(BK,'removed_'+f.replace('/','_')))
    print('UNDONE: blog page and sitemap restored, the two posts removed. Click Republish.'); sys.exit()
blog=rd('blog/index.html'); site=rd('sitemap.xml')
if all(os.path.exists(f) and sha(rd(f))==v['h'] for f,v in C['files'].items()) and C['cards'].encode() in blog:
    print('Already done. Nothing to change.'); sys.exit()
bad=[]
if blog.count(C['hr'].encode())!=1: bad.append('blog/index.html (the gold rule line was not found exactly once)')
if blog.count(b'<!DOCTYPE')!=1: bad.append('blog/index.html (not exactly one DOCTYPE)')
if site.count(b'</urlset>')!=1: bad.append('sitemap.xml (end tag)')
for f in C['files']:
    if os.path.exists(f): bad.append(f+' (already exists)')
    if f.encode() in blog: bad.append('blog/index.html already links '+f)
if bad:
    print('STOP. Nothing was changed:'); print('\n'.join(bad)); sys.exit(1)
os.makedirs(BK,exist_ok=True)
for f in EDIT: shutil.copyfile(f,os.path.join(BK,f.replace('/','_')))
for f,v in C['files'].items():
    b=zlib.decompress(base64.b64decode(v['d'])); assert sha(b)==v['h']
    open(f,'wb').write(b)
hr=C['hr'].encode()
open('blog/index.html','wb').write(blog.replace(hr,hr+C['cards'].encode(),1))
open('sitemap.xml','wb').write(site.replace(b'</urlset>',C['smap'].encode()+b'</urlset>',1))
b2=rd('blog/index.html'); s2=rd('sitemap.xml')
ok=all(sha(rd(f))==v['h'] for f,v in C['files'].items()) and b2.count(b'<!DOCTYPE')==1 and s2.count(b'<loc>')==site.count(b'<loc>')+2
print('DONE: two answer posts added to the blog and sitemap. Click Republish.' if ok else 'CHECK FAILED. Run: python3 answers_oct28.py --undo')
